# 실제 사람 시연 사진(시작·끝 자세 2장): free-exercise-db (https://github.com/yuhonas/free-exercise-db, Unlicense)
PHOTOS = {
    # 사진 내용을 한 장씩 확인해 동작 설명과 같은 것만 넣었다 (기구에서 하는 사진은 제외)
    "맨몸 스쿼트": "Bodyweight_Squat", "고블릿 스쿼트": "Goblet_Squat", "리버스 런지": "Dumbbell_Rear_Lunge",
    "인클라인 푸시업": "Incline_Push-Up", "푸시업": "Pushups",
    "플랭크": "Plank", "데드버그": "Dead_Bug", "가벼운 덤벨 레이즈": "Side_Lateral_Raise",
    "덤벨 컬": "Dumbbell_Bicep_Curl", "덤벨 로우": "One-Arm_Dumbbell_Row",
}
PHOTO_BASE = "https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/"
PHOTO_CREDIT = "실제 시연 사진 · free-exercise-db (퍼블릭 도메인)"
PHOTO_NOTES = {"리버스 런지": "사진은 덤벨을 들었지만 맨몸으로 같은 동작을 해요."}

DISCLAIMER = "일반적인 생활 운동 안내예요. 통증이 있으면 멈추고, 질환이나 부상이 있으면 전문가와 상의하세요."


def describe(name):
    motion, prop, steps, breath, caution, muscles = LIBRARY.get(name, LIBRARY["제자리 걷기"])
    photo = PHOTOS.get(name)
    frames = [PHOTO_BASE + f"{photo}/{i}.jpg" for i in (0, 1)] if photo else []
    return {"name": name, "motion": motion, "prop": prop, "how": steps, "breath": breath, "caution": caution, "muscles": muscles, "photos": frames, "photo_note": PHOTO_NOTES.get(name, "")}
